# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

# A refused save records its failed intent and abort row only after the
# outermost transaction has ended, so these examples run on committed data.
RSpec.describe "Invoice saves under the prepared monolith owner", committed_data: true do
  include PreparedReservationsSpecSupport

  # "a draft adds an entry, leaving a committed reservation row and a committed intent; a second kept invoice on that entry is refused with \"entry is on another invoice\""
  # "a refused prepare reserves nothing and leaves a failed intent with an abort row"
  it "under the prepared owner a draft gaining a line commits a reservation and its intent, and a second kept invoice on that entry is refused with a failed intent and a delivered abort row" do
    company = create(:company)
    entry = prepared_spec_projected_entry(company)
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    client = create(:client, company:)
    draft = create(:invoice, company:, client:)

    create(:invoice_line_item, invoice: draft, timesheet_entry: entry, rate: 100, quantity: 60)

    reservations_sql = ActiveRecord::Base.sanitize_sql_array(
      ["SELECT entry_id, invoice_id, state, disposition FROM reservations WHERE company_id = ?", company.id]
    )
    expect(ActiveRecord::Base.connection.select_all(reservations_sql).cast_values)
      .to eq([[entry.id, draft.id, "committed", "active"]])
    expect(InvoiceOperationIntent.where(company_id: company.id, invoice_id: draft.id).pluck(:state)).to eq(["committed"])
    expect(InvoiceOperationOutboxItem.where(company_id: company.id, invoice_id: draft.id, kind: "commit")
      .pluck(:delivered_at)).to all(be_present)
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company.id, entry_id: entry.id).count).to eq(1)

    second_id = nil
    expect do
      ApplicationRecord.transaction do
        second = create(:invoice, company:, client:)
        second_id = second.id
        create(:invoice_line_item, invoice: second, timesheet_entry: entry, rate: 100, quantity: 60)
      end
    end.to raise_error(Invoices::OperationErrors::Refused) { |error|
      expect(error.outcome.conflicts).to eq([{ entry_id: entry.id, reason: "on_another_invoice" }])
    }

    expect(ActiveRecord::Base.connection.select_all(reservations_sql).cast_values)
      .to eq([[entry.id, draft.id, "committed", "active"]])
    expect(InvoiceOperationIntent.where(company_id: company.id, invoice_id: second_id).pluck(:state)).to eq(["failed"])
    abort_rows = InvoiceOperationOutboxItem.where(company_id: company.id, invoice_id: second_id)
    expect(abort_rows.pluck(:kind)).to eq(["abort"])
    expect(abort_rows.first.delivered_at).to be_present
    expect(abort_rows.first.attempts).to eq(0)
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company.id, entry_id: entry.id).count).to eq(1)
  end
end

RSpec.describe Invoices::PreparedReservations, "invoice discards under the prepared owner", committed_data: true do
  include PreparedReservationsSpecSupport

  # "A discarded draft releases; a discarded non-draft keeps its reservations as retained"
  it "under the prepared owner a discarded draft releases its entry while a discarded sent invoice keeps its entry committed as retained" do
    company = create(:company)
    client = create(:client, company:)
    project = create(:project, client:, billable: true)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    entries = Array.new(2) { prepared_spec_projected_entry(company, user:, project:) }
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    rows = lambda do |entry|
      ActiveRecord::Base.connection.select_rows(ActiveRecord::Base.sanitize_sql_array([<<~SQL.squish, company.id, entry.id]))
        SELECT state, disposition FROM reservations WHERE company_id = ? AND entry_id = ?
      SQL
    end

    draft = create(:invoice, company:, client:, status: :draft, invoice_number: "PREP-DISCARD-DRAFT")
    create(:invoice_line_item, invoice: draft, timesheet_entry: entries.first, rate: 100, quantity: 60)
    sent = create(:invoice, company:, client:, status: :draft, invoice_number: "PREP-DISCARD-SENT")
    create(:invoice_line_item, invoice: sent, timesheet_entry: entries.last, rate: 100, quantity: 60)
    expect([rows.call(entries.first), rows.call(entries.last)]).to eq([[%w[committed active]], [%w[committed active]]])
    sent.update_columns(status: Invoice.statuses.fetch("sent"))

    Invoice.find(draft.id).discard!
    Invoice.find(sent.id).discard!

    expect(rows.call(entries.first)).to eq([])
    expect(rows.call(entries.last)).to eq([%w[committed retained]])
  end
end

RSpec.describe Invoices::PreparedReservations, "end-to-end saves under the prepared owner", committed_data: true do
  include PreparedReservationsSpecSupport

  let(:prepared_e2e_company) { create(:company) }
  let(:prepared_e2e_client) { create(:client, company: prepared_e2e_company) }
  # Entries sit under the invoices' own client, so their lines belong on those invoices.
  let(:prepared_e2e_project) { create(:project, client: prepared_e2e_client, billable: true) }

  before do
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
  end

  def prepared_e2e_reservations(entry)
    ActiveRecord::Base.connection.select_rows(ActiveRecord::Base.sanitize_sql_array([<<~SQL.squish, prepared_e2e_company.id, entry.id]))
      SELECT invoice_id, state, disposition FROM reservations WHERE company_id = ? AND entry_id = ? ORDER BY invoice_id
    SQL
  end

  def prepared_e2e_outbox_count(entry)
    Timekeeping::LocalOutboxEntry.where(company_id: prepared_e2e_company.id, entry_id: entry.id).count
  end

  def prepared_e2e_version(entry)
    Timekeeping::LocalEntry.find_by!(company_id: prepared_e2e_company.id, id: entry.id).version
  end

  def prepared_e2e_invoice(status: :draft)
    create(:invoice, company: prepared_e2e_company, client: prepared_e2e_client, status:)
  end

  # "A second kept invoice on the same entry fails with \"entry is on another invoice\""
  it "refuses a draft taking an entry that a sent invoice holds only through its line, and reserves nothing" do
    entry = prepared_spec_projected_entry(prepared_e2e_company, project: prepared_e2e_project)
    sent = prepared_e2e_invoice(status: :sent)
    create(:invoice_line_item, invoice: sent, timesheet_entry: entry, rate: 100, quantity: 60)
    expect(prepared_e2e_reservations(entry)).to eq([])

    draft_id = nil
    expect do
      ApplicationRecord.transaction do
        draft = prepared_e2e_invoice
        draft_id = draft.id
        create(:invoice_line_item, invoice: draft, timesheet_entry: entry, rate: 100, quantity: 60)
      end
    end.to raise_error(Invoices::OperationErrors::Refused) { |error|
      expect(error.outcome.conflicts).to eq([{ entry_id: entry.id, reason: "on_another_invoice" }])
    }

    expect(prepared_e2e_reservations(entry)).to eq([])
    expect(InvoiceOperationIntent.where(company_id: prepared_e2e_company.id, invoice_id: draft_id).pluck(:state))
      .to eq(["failed"])
    expect(prepared_e2e_outbox_count(entry)).to eq(0)
  end

  # "drops another invoice's `retained` reservation on the same entry"
  it "lets a later kept invoice claim an entry a discarded sent invoice retains, replacing the retained row" do
    entry = prepared_spec_projected_entry(prepared_e2e_company, project: prepared_e2e_project)
    old = prepared_e2e_invoice
    create(:invoice_line_item, invoice: old, timesheet_entry: entry, rate: 100, quantity: 60)
    old.update_columns(status: Invoice.statuses.fetch("sent"))
    Invoice.find(old.id).discard!
    expect(prepared_e2e_reservations(entry)).to eq([[old.id, "committed", "retained"]])

    successor = prepared_e2e_invoice
    create(:invoice_line_item, invoice: successor, timesheet_entry: entry, rate: 100, quantity: 60)

    expect(prepared_e2e_reservations(entry)).to eq([[successor.id, "committed", "active"]])
    expect(InvoiceOperationIntent.where(company_id: prepared_e2e_company.id, invoice_id: successor.id).pluck(:state))
      .to eq(["committed"])
  end

  # "a locked change writes exactly one `entry_outbox_items` row"
  it "publishes one snapshot and one version raise for the entry a save locks, and none for an entry it keeps locked" do
    held = prepared_spec_projected_entry(prepared_e2e_company, project: prepared_e2e_project)
    added = prepared_spec_projected_entry(prepared_e2e_company, project: prepared_e2e_project)
    draft = prepared_e2e_invoice
    create(:invoice_line_item, invoice: draft, timesheet_entry: held, rate: 100, quantity: 60)
    held_version = prepared_e2e_version(held)
    added_version = prepared_e2e_version(added)
    expect(prepared_e2e_outbox_count(held)).to eq(1)
    expect(prepared_e2e_outbox_count(added)).to eq(0)

    create(:invoice_line_item, invoice: Invoice.find(draft.id), timesheet_entry: added, rate: 100, quantity: 60)

    expect(prepared_e2e_reservations(added)).to eq([[draft.id, "committed", "active"]])
    expect(prepared_e2e_outbox_count(added)).to eq(1)
    expect(prepared_e2e_version(added)).to eq(added_version + 1)
    expect(prepared_e2e_outbox_count(held)).to eq(1)
    expect(prepared_e2e_version(held)).to eq(held_version)
    payload = Timekeeping::LocalOutboxEntry.find_by!(company_id: prepared_e2e_company.id, entry_id: added.id).payload
    expect(payload.keys).to match_array(TimekeepingContract.load(:entry_snapshots).fetch("entry_fields"))
    expect(payload["locked"]).to be(true)
  end
end
